const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'resources') throw new Error('unsupported_resource');
const recordId = text(fields.resource_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const requested = text(fields.status);
const RESOURCE_STATUSES = ['available', 'assigned', 'deployed', 'unavailable', 'maintenance', 'retired'];
if (!RESOURCE_STATUSES.includes(requested)) throw new Error('invalid_resource_status');
const note = text(fields.note);
if (note.length > 4000) throw new Error('note_max_4000');
const allowed = new Set(['resource_id', 'status', 'note']);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const audit = {
  product, resource, operation: 'resource.status', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return { recordId, encodedId: encodeURIComponent(recordId), requested, note, audit };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('resource_unit_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const unit = { ...current.data, id: String(current.data.id || current.id) };
const requested = String(state.requested);
const currentStatus = typeof unit.status === 'string' && unit.status ? String(unit.status) : 'available';
if (currentStatus === requested) {
  return { idempotent: true, resource_id: unit.id, status: currentStatus };
}
// retired is terminal (commit 2a79cc1): a retired unit is immutable.
if (currentStatus === 'retired') throw new Error('record_immutable');
const ALLOWED_FROM = {
  available: ['unavailable', 'maintenance'],
  assigned: ['available'],
  deployed: ['available', 'assigned'],
  unavailable: ['available'],
  maintenance: ['available'],
  retired: ['available', 'unavailable', 'maintenance'],
};
const allowedFrom = ALLOWED_FROM[requested] || [];
if (!allowedFrom.includes(currentStatus)) throw new Error('invalid_resource_transition');
const history = Array.isArray(unit.status_history) ? [...unit.status_history] : [];
history.push({ from: currentStatus, to: requested, at: $now, by: state.audit.submittedBy, note: state.note || null });
const next = { ...unit, status: requested, status_changed_at: $now, status_history: history, updated_at: $now };
if (requested === 'retired') next.retired_at = $now;
return { body: { data: next, ifVersion: current.version }, encodedId: state.encodedId, audit: state.audit, operation: state.operation };

const state = $input || {};
if (state.idempotent !== true) throw new Error('unexpected_lifecycle_mode');
return { idempotent: true, operation: 'resource.status', resource_id: state.resource_id, status: state.status };
